from pathlib import Path
from datetime import datetime

ROOT = Path.cwd()
FRONTEND = ROOT / 'frontend'
if not FRONTEND.exists():
    raise SystemExit('❌ 請在專案根目錄執行，例如：cd ~/Downloads/active-etf-tracker-fix')

now = datetime.now().strftime('%Y%m%d_%H%M%S')

def backup(path: Path):
    if path.exists():
        bak = path.with_suffix(path.suffix + f'.bak_v112_{now}')
        bak.write_text(path.read_text(encoding='utf-8'), encoding='utf-8')
        print(f'備份：{path} -> {bak.name}')

def write(path: Path, content: str):
    path.parent.mkdir(parents=True, exist_ok=True)
    backup(path)
    path.write_text(content.strip() + '\n', encoding='utf-8')
    print(f'✅ 寫入 {path}')

signals_v112 = "\nimport { createClient } from '@supabase/supabase-js';\n\nexport const ACTIVE_ETF_CODES_V112 = [\n  '00400A','00401A','00402A','00403A','00404A','00405A','00406A',\n  '00980A','00981A','00982A','00983A','00984A','00985A','00986A','00987A','00988A','00989A','00990A','00991A','00992A','00993A','00994A','00995A','00996A','00997A','00998A','00999A',\n];\n\nconst ETF_NAME_FALLBACK: Record<string, string> = {\n  '00400A': '主動國泰動能高息',\n  '00401A': '主動摩根台灣鑫收',\n  '00402A': '主動安聯美國科技',\n  '00403A': '主動統一升級50',\n  '00404A': '主動聯博動能50',\n  '00405A': '主動富邦台灣龍耀',\n  '00406A': '主動中信台灣收益',\n  '00980A': '主動野村臺灣優選',\n  '00981A': '主動統一台股增長',\n  '00982A': '主動群益台灣強棒',\n  '00983A': '主動中信成長高股息',\n  '00984A': '主動安聯台灣高息成長',\n  '00985A': '主動野村台灣50',\n  '00986A': '主動凱基台灣AI50',\n  '00987A': '主動凱基台灣精選',\n  '00988A': '主動統一全球創新',\n  '00989A': '主動野村台灣50',\n  '00990A': '主動元大AI新經濟',\n  '00991A': '主動復華未來50',\n  '00992A': '主動群益科技創新',\n  '00993A': '主動安聯台灣',\n  '00994A': '主動第一金台股優',\n  '00995A': '主動野村台灣優選高息',\n  '00996A': '主動兆豐台灣豐收',\n  '00997A': '主動群益美國增長',\n  '00998A': '主動復華金融股息',\n  '00999A': '主動野村臺灣高息',\n};\n\ntype AnyRow = Record<string, any>;\n\nfunction n(v: any, fallback = 0): number {\n  if (v === null || v === undefined || v === '') return fallback;\n  const x = Number(String(v).replace(/,/g, '').replace(/[^\\d.-]/g, ''));\n  return Number.isFinite(x) ? x : fallback;\n}\nfunction isActiveEtf(code: any) {\n  return /^[0-9]{5}A$/.test(String(code || '').trim().toUpperCase());\n}\nfunction isTwStock(code: any) {\n  return /^[0-9]{4}$/.test(String(code || '').trim());\n}\nfunction dateOnly(v: any) {\n  const s = String(v || '').trim();\n  const m = s.match(/(\\d{4}-\\d{2}-\\d{2})/);\n  return m ? m[1] : s;\n}\nfunction minusDays(date: string, days: number) {\n  const d = new Date(`${date}T00:00:00+08:00`);\n  d.setDate(d.getDate() - days);\n  const y = d.getFullYear();\n  const m = String(d.getMonth() + 1).padStart(2, '0');\n  const day = String(d.getDate()).padStart(2, '0');\n  return `${y}-${m}-${day}`;\n}\nasync function selectPaged(supabase: any, table: string, columns: string, build: (q: any) => any, pageSize = 1000, maxRows = 80000) {\n  const out: AnyRow[] = [];\n  for (let from = 0; from < maxRows; from += pageSize) {\n    const to = from + pageSize - 1;\n    const { data, error } = await build(supabase.from(table).select(columns)).range(from, to);\n    if (error) {\n      const msg = String(error.message || '');\n      if (msg.includes('does not exist') || msg.includes('Could not find the table')) return [];\n      throw new Error(`${table}: ${msg}`);\n    }\n    out.push(...(data || []));\n    if (!data || data.length < pageSize) break;\n  }\n  return out;\n}\nfunction buildStockMap(rows: AnyRow[]) {\n  const map: Record<string, AnyRow> = {};\n  for (const r of rows || []) {\n    const code = String(r.stock_code || '').trim();\n    if (!isTwStock(code)) continue;\n    if (!map[code]) map[code] = { stock_code: code, stock_name: r.stock_name || code, shares: 0, weight: 0 };\n    map[code].stock_name = r.stock_name || map[code].stock_name || code;\n    map[code].shares += n(r.shares, 0);\n    map[code].weight += n(r.weight, 0);\n  }\n  return map;\n}\nfunction quoteMap(rows: AnyRow[]) {\n  const map: Record<string, AnyRow> = {};\n  for (const r of rows || []) {\n    const c = String(r.stock_code || r.code || '').trim();\n    if (c) map[c] = r;\n  }\n  return map;\n}\nfunction qPrice(q: AnyRow | undefined) {\n  const x = n(q?.price, NaN);\n  return Number.isFinite(x) && x > 0 ? x : null;\n}\nfunction qPct(q: AnyRow | undefined) {\n  const x = n(q?.change_pct, NaN);\n  return Number.isFinite(x) ? x : null;\n}\n\nexport async function getSignalsV112() {\n  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;\n  const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;\n  if (!url || !key) {\n    return {\n      rows: [],\n      total_etf_count: ACTIVE_ETF_CODES_V112.length,\n      fetched_etf_count: 0,\n      today_etf_count: 0,\n      non_today_etf_count: ACTIVE_ETF_CODES_V112.length,\n      data_date: '',\n      warning: '缺少 NEXT_PUBLIC_SUPABASE_URL 或 NEXT_PUBLIC_SUPABASE_ANON_KEY',\n    };\n  }\n\n  const supabase = createClient(url, key, { auth: { persistSession: false } });\n\n  const dateRows = await selectPaged(\n    supabase,\n    'holdings',\n    'etf_code,data_date',\n    (q) => q.order('data_date', { ascending: false }),\n    1000,\n    100000,\n  );\n\n  const codeSet = new Set<string>(ACTIVE_ETF_CODES_V112);\n  const latestByEtf: Record<string, string> = {};\n  for (const r of dateRows || []) {\n    const c = String(r.etf_code || '').trim().toUpperCase();\n    const d = dateOnly(r.data_date);\n    if (!isActiveEtf(c) || !d) continue;\n    codeSet.add(c);\n    if (!latestByEtf[c] || d > latestByEtf[c]) latestByEtf[c] = d;\n  }\n\n  const targetDate = Object.values(latestByEtf).sort().pop() || '';\n  const totalEtfs = codeSet.size;\n  const todayEtfs = Object.entries(latestByEtf).filter(([, d]) => d === targetDate).map(([c]) => c);\n  const todayEtfSet = new Set(todayEtfs);\n  const nonTodayEtfs = Array.from(codeSet).filter((c) => latestByEtf[c] !== targetDate);\n\n  if (!targetDate || todayEtfs.length === 0) {\n    return {\n      rows: [],\n      total_etf_count: totalEtfs,\n      fetched_etf_count: 0,\n      today_etf_count: 0,\n      non_today_etf_count: totalEtfs,\n      data_date: targetDate,\n      non_today_etfs: nonTodayEtfs,\n    };\n  }\n\n  const fromDate = minusDays(targetDate, 35);\n  const [holdingRows, stockQuoteRows] = await Promise.all([\n    selectPaged(\n      supabase,\n      'holdings',\n      'etf_code,data_date,stock_code,stock_name,shares,weight',\n      (q) => q.gte('data_date', fromDate).lte('data_date', targetDate).order('data_date', { ascending: true }),\n      1000,\n      120000,\n    ),\n    selectPaged(supabase, 'stock_quotes', '*', (q) => q, 1000, 5000),\n  ]);\n\n  const sq = quoteMap(stockQuoteRows || []);\n  const grouped: Record<string, Record<string, AnyRow[]>> = {};\n  for (const r of holdingRows || []) {\n    const etf = String(r.etf_code || '').trim().toUpperCase();\n    if (!todayEtfSet.has(etf)) continue;\n    const d = dateOnly(r.data_date);\n    if (!d) continue;\n    if (!grouped[etf]) grouped[etf] = {};\n    if (!grouped[etf][d]) grouped[etf][d] = [];\n    grouped[etf][d].push(r);\n  }\n\n  const byStock: Record<string, AnyRow> = {};\n  for (const etf of todayEtfs) {\n    const dates = Object.keys(grouped[etf] || {}).sort();\n    const latest = dates.filter((d) => d === targetDate).pop();\n    const prev = dates.filter((d) => d < targetDate).pop();\n    if (!latest || !prev) continue;\n\n    const currMap = buildStockMap(grouped[etf][latest] || []);\n    const prevMap = buildStockMap(grouped[etf][prev] || []);\n    const allStocks = new Set([...Object.keys(currMap), ...Object.keys(prevMap)]);\n\n    for (const stock of allStocks) {\n      const curr = currMap[stock];\n      const pre = prevMap[stock];\n      const currShares = n(curr?.shares, 0);\n      const prevShares = n(pre?.shares, 0);\n      const deltaShares = currShares - prevShares;\n      if (Math.abs(deltaShares) < 1) continue;\n\n      const deltaLots = deltaShares / 1000;\n      if (!byStock[stock]) {\n        const q = sq[stock] || {};\n        byStock[stock] = {\n          stock_code: stock,\n          code: stock,\n          stock_name: curr?.stock_name || pre?.stock_name || q.stock_name || q.name || stock,\n          name: curr?.stock_name || pre?.stock_name || q.stock_name || q.name || stock,\n          price: qPrice(q),\n          change_pct: qPct(q),\n          curr_shares: 0,\n          prev_shares: 0,\n          net_lots: 0,\n          buy_count: 0,\n          sell_count: 0,\n          add_etf_count: 0,\n          reduce_etf_count: 0,\n          data_date: targetDate,\n          etf_changes: [],\n        };\n      }\n      const item = byStock[stock];\n      item.curr_shares += currShares;\n      item.prev_shares += prevShares;\n      item.net_lots += deltaLots;\n      if (deltaLots > 0) {\n        item.buy_count += 1;\n        item.add_etf_count += 1;\n      }\n      if (deltaLots < 0) {\n        item.sell_count += 1;\n        item.reduce_etf_count += 1;\n      }\n      item.etf_changes.push({\n        etf_code: etf,\n        etf_name: ETF_NAME_FALLBACK[etf] || etf,\n        data_date: targetDate,\n        previous_date: prev,\n        delta_lots: deltaLots,\n        curr_lots: currShares / 1000,\n        prev_lots: prevShares / 1000,\n      });\n    }\n  }\n\n  const rows = Object.values(byStock).map((r: AnyRow) => {\n    const price = r.price;\n    const netAmount = price ? price * r.net_lots * 1000 / 100000000 : 0;\n    const currLots = r.curr_shares / 1000;\n    const prevLots = r.prev_shares / 1000;\n    let status = '異動';\n    if (prevLots <= 0 && currLots > 0) status = '新增';\n    else if (currLots <= 0 && prevLots > 0) status = '刪除';\n    else if (r.net_lots > 0) status = '加碼';\n    else if (r.net_lots < 0) status = '減碼';\n    return {\n      ...r,\n      status,\n      type: status,\n      current_lots: currLots,\n      previous_lots: prevLots,\n      net_amount_billion: netAmount,\n      delta_amount_billion: netAmount,\n      amount_billion: netAmount,\n    };\n  }).filter((r) => ['新增', '刪除', '加碼', '減碼'].includes(r.status));\n\n  const statusCount: Record<string, number> = { 新增: 0, 刪除: 0, 加碼: 0, 減碼: 0 };\n  for (const r of rows) statusCount[r.status] = (statusCount[r.status] || 0) + 1;\n\n  return {\n    rows,\n    changes: rows,\n    aggregate: rows,\n    data_date: targetDate,\n    target_date: targetDate,\n    total_etf_count: totalEtfs,\n    fetched_etf_count: todayEtfs.length,\n    today_etf_count: todayEtfs.length,\n    non_today_etf_count: nonTodayEtfs.length,\n    today_etfs: todayEtfs,\n    non_today_etfs: nonTodayEtfs,\n    status_count: statusCount,\n    note: `本頁僅統計 ${targetDate} 已更新的 ETF；未更新 ETF 不混入前一日資料。`,\n  };\n}\n"
signals_client = '\n\'use client\';\n\nimport Link from \'next/link\';\nimport { useMemo, useState } from \'react\';\n\ntype AnyRow = Record<string, any>;\ntype SortKey = \'inflow\' | \'outflow\' | \'abs_amount\' | \'lots\' | \'buy\' | \'sell\' | \'price\' | \'pct\';\ntype Status = \'新增\' | \'刪除\' | \'加碼\' | \'減碼\';\n\nconst STATUSES: Status[] = [\'新增\', \'刪除\', \'加碼\', \'減碼\'];\n\nfunction num(v: any, fallback = 0): number {\n  if (v === null || v === undefined || v === \'\') return fallback;\n  const x = Number(String(v).replace(/,/g, \'\').replace(/[^\\d.-]/g, \'\'));\n  return Number.isFinite(x) ? x : fallback;\n}\nfunction firstNum(row: AnyRow, keys: string[], fallback = 0): number {\n  for (const k of keys) {\n    if (row && row[k] !== undefined && row[k] !== null && row[k] !== \'\') {\n      const v = num(row[k], NaN);\n      if (Number.isFinite(v)) return v;\n    }\n  }\n  return fallback;\n}\nfunction rowsOf(data: any): AnyRow[] {\n  const src = data?.rows ?? data?.changes ?? data?.aggregate ?? data?.items ?? [];\n  return Array.isArray(src) ? src : [];\n}\nfunction codeOf(row: AnyRow) { return String(row.stock_code ?? row.code ?? \'\').trim(); }\nfunction nameOf(row: AnyRow) { return String(row.stock_name ?? row.name ?? row.stockName ?? codeOf(row)).trim(); }\nfunction priceOf(row: AnyRow) {\n  const v = firstNum(row, [\'price\', \'close_price\', \'close\', \'last_price\'], NaN);\n  return Number.isFinite(v) ? v : null;\n}\nfunction pctOf(row: AnyRow) {\n  const v = firstNum(row, [\'change_pct\', \'pct\', \'percent\', \'changePercent\'], NaN);\n  return Number.isFinite(v) ? v : null;\n}\nfunction lotsOf(row: AnyRow) {\n  return firstNum(row, [\'net_lots\', \'display_delta_lots\', \'change_lots\', \'delta_lots\', \'lot_change\'], 0);\n}\nfunction amountOf(row: AnyRow) {\n  const direct = firstNum(row, [\'net_amount_billion\', \'delta_amount_billion\', \'flow_billion\', \'money_billion\', \'amount_billion\'], NaN);\n  if (Number.isFinite(direct)) return direct;\n  const p = priceOf(row);\n  return p ? p * lotsOf(row) * 1000 / 100000000 : 0;\n}\nfunction statusOf(row: AnyRow): Status {\n  const s = String(row.status ?? row.type ?? \'\').trim();\n  if (STATUSES.includes(s as Status)) return s as Status;\n  const lots = lotsOf(row);\n  if (lots > 0) return \'加碼\';\n  if (lots < 0) return \'減碼\';\n  return \'加碼\';\n}\nfunction buyOf(row: AnyRow) {\n  return Math.max(0, Math.round(firstNum(row, [\'buy_count\', \'buy_etf_count\', \'add_etf_count\', \'increase_count\'], 0)));\n}\nfunction sellOf(row: AnyRow) {\n  return Math.max(0, Math.round(firstNum(row, [\'sell_count\', \'sell_etf_count\', \'reduce_etf_count\', \'decrease_count\'], 0)));\n}\nfunction mmdd(dateLike: any) {\n  const s = String(dateLike ?? \'\').trim();\n  const m = s.match(/(\\d{4})-(\\d{2})-(\\d{2})/);\n  if (m) return `${m[2]}-${m[3]}`;\n  return s;\n}\nfunction fmt0(v: any) {\n  const x = num(v, NaN);\n  if (!Number.isFinite(x)) return \'-\';\n  return Math.round(x).toLocaleString(\'zh-TW\');\n}\nfunction fmtPrice(v: number | null) {\n  if (v === null || !Number.isFinite(v)) return \'-\';\n  return v.toLocaleString(\'zh-TW\', { maximumFractionDigits: v >= 100 ? 1 : 2 });\n}\nfunction fmtPct(v: number | null) {\n  if (v === null || !Number.isFinite(v)) return \'-\';\n  const sign = v > 0 ? \'+\' : \'\';\n  return `${sign}${v.toFixed(2)}%`;\n}\nfunction fmtLots(v: number) {\n  if (!Number.isFinite(v)) return \'-\';\n  if (Math.abs(v) < 0.01) return \'0張\';\n  const sign = v > 0 ? \'+\' : \'\';\n  return `${sign}${Math.round(v).toLocaleString(\'zh-TW\')}張`;\n}\nfunction fmtBillion(v: number) {\n  if (!Number.isFinite(v)) return \'-\';\n  if (Math.abs(v) < 0.005) return \'0億\';\n  const sign = v > 0 ? \'+\' : \'\';\n  const abs = Math.abs(v);\n  const digits = abs >= 100 ? 1 : abs >= 10 ? 1 : 2;\n  return `${sign}${v.toLocaleString(\'zh-TW\', { maximumFractionDigits: digits })}億`;\n}\nfunction tone(v: number) { return v > 0 ? \'red\' : v < 0 ? \'green\' : \'muted\'; }\nfunction isLimitUp(row: AnyRow) { const p = pctOf(row); return p !== null && p >= 9.7; }\nfunction isLimitDown(row: AnyRow) { const p = pctOf(row); return p !== null && p <= -9.7; }\n\nfunction DataQuality({ data }: { data: any }) {\n  const total = Number(data?.total_etf_count ?? data?.totalEtfCount ?? 0);\n  const today = Number(data?.today_etf_count ?? data?.fetched_etf_count ?? data?.includedEtfCount ?? 0);\n  const missing = Number(data?.non_today_etf_count ?? Math.max(0, total - today));\n  const date = data?.target_date ?? data?.data_date ?? data?.latestDataDate ?? \'\';\n  return (\n    <div className="v112-quality">\n      <div className="v112-quality-main">資料日 {date ? mmdd(date) : \'-\'}</div>\n      <div className="v112-quality-sub">\n        已取得今日資料：<b>{today}</b> / <b>{total || today}</b> 檔 ETF\n        {missing > 0 ? <span className="v112-warn">未更新 {missing} 檔，本頁不混入前一日資料</span> : <span>資料完整</span>}\n      </div>\n    </div>\n  );\n}\n\nfunction FocusCard({ title, row, kind }: { title: string; row?: AnyRow | null; kind: \'red\' | \'green\' }) {\n  if (!row) {\n    return <div className={`v112-focus-card ${kind}`}><div className="v112-focus-title">{title}</div><div className="v112-empty">尚無有效訊號</div></div>;\n  }\n  const amount = amountOf(row);\n  const lots = lotsOf(row);\n  const price = priceOf(row);\n  const pct = pctOf(row);\n  return (\n    <Link href={`/stock/${codeOf(row)}`} className={`v112-focus-card ${kind}`}>\n      <div className="v112-focus-title">{title}</div>\n      <div className="v112-focus-name"><span>{nameOf(row)}</span><em>{codeOf(row)}</em></div>\n      <div className="v112-focus-price"><span>{fmtPrice(price)}</span><b className={tone(pct ?? 0)}>{fmtPct(pct)}</b></div>\n      <div className="v112-focus-meta"><span>淨額 <b className={tone(amount)}>{fmtBillion(amount)}</b></span><span>張數 <b className={tone(lots)}>{fmtLots(lots)}</b></span><span>買賣 {buyOf(row)}:{sellOf(row)}</span></div>\n    </Link>\n  );\n}\n\nfunction SortPill({ label, active, onClick }: { label: string; active: boolean; onClick: () => void }) {\n  return <button type="button" onClick={onClick} className={`v112-sort-pill ${active ? \'active\' : \'\'}`}>{label}</button>;\n}\nfunction StatusPill({ label, count, active, onClick }: { label: Status; count: number; active: boolean; onClick: () => void }) {\n  return <button type="button" onClick={onClick} className={`v112-status-pill s-${label} ${active ? \'active\' : \'\'}`}>{label} {count}</button>;\n}\n\nfunction SignalRow({ row }: { row: AnyRow }) {\n  const code = codeOf(row);\n  const amount = amountOf(row);\n  const lots = lotsOf(row);\n  const pct = pctOf(row);\n  const status = statusOf(row);\n  return (\n    <Link href={`/stock/${code}`} className="v112-row">\n      <div className="v112-r-main">\n        <div className="v112-r-name">{nameOf(row)}<span>{code}</span></div>\n        <div className="v112-r-price"><span className={isLimitUp(row) ? \'limit-up\' : isLimitDown(row) ? \'limit-down\' : \'\'}>{fmtPrice(priceOf(row))}</span><b className={tone(pct ?? 0)}>{fmtPct(pct)}</b></div>\n        <div className="v112-r-amount"><b className={tone(amount)}>{fmtBillion(amount)}</b><span className={tone(lots)}>{fmtLots(lots)}</span></div>\n      </div>\n      <div className="v112-r-sub">\n        <span className={`v112-status s-${status}`}>{status}</span>\n        <span>買賣 {buyOf(row)}:{sellOf(row)}</span>\n        {isLimitUp(row) && <span className="v112-limit up">漲停</span>}\n        {isLimitDown(row) && <span className="v112-limit down">跌停</span>}\n      </div>\n    </Link>\n  );\n}\n\nexport default function SignalsClient(props: any) {\n  const data = props?.data ?? props ?? {};\n  const sourceRows = rowsOf(data).filter((r) => STATUSES.includes(statusOf(r)) && codeOf(r));\n  const [period, setPeriod] = useState<\'today\' | \'5\' | \'10\' | \'20\'>(\'today\');\n  const [selectedStatuses, setSelectedStatuses] = useState<Status[]>([\'新增\', \'刪除\', \'加碼\', \'減碼\']);\n  const [sortKey, setSortKey] = useState<SortKey>(\'inflow\');\n\n  const statusCount = useMemo(() => {\n    const out: Record<Status, number> = { 新增: 0, 刪除: 0, 加碼: 0, 減碼: 0 };\n    for (const r of sourceRows) out[statusOf(r)] += 1;\n    return out;\n  }, [sourceRows]);\n\n  const rows = useMemo(() => {\n    const filtered = sourceRows.filter((r) => selectedStatuses.includes(statusOf(r)));\n    const value = (r: AnyRow) => {\n      if (sortKey === \'inflow\') return amountOf(r);\n      if (sortKey === \'outflow\') return -amountOf(r);\n      if (sortKey === \'abs_amount\') return Math.abs(amountOf(r));\n      if (sortKey === \'lots\') return Math.abs(lotsOf(r));\n      if (sortKey === \'buy\') return buyOf(r);\n      if (sortKey === \'sell\') return sellOf(r);\n      if (sortKey === \'price\') return priceOf(r) ?? -Infinity;\n      if (sortKey === \'pct\') return pctOf(r) ?? -Infinity;\n      return 0;\n    };\n    return [...filtered].sort((a, b) => value(b) - value(a));\n  }, [sourceRows, selectedStatuses, sortKey]);\n\n  const focus = useMemo(() => {\n    const pos = sourceRows.filter((r) => amountOf(r) > 0);\n    const neg = sourceRows.filter((r) => amountOf(r) < 0);\n    const max = (arr: AnyRow[], fn: (r: AnyRow) => number) => arr.length ? [...arr].sort((a, b) => fn(b) - fn(a))[0] : null;\n    return {\n      inflow: max(pos, amountOf),\n      outflow: max(neg, (r) => Math.abs(amountOf(r))),\n      mostAdd: max(sourceRows.filter((r) => buyOf(r) > 0), (r) => buyOf(r) * 1000000 + Math.max(0, lotsOf(r))),\n      mostReduce: max(sourceRows.filter((r) => sellOf(r) > 0), (r) => sellOf(r) * 1000000 + Math.abs(Math.min(0, lotsOf(r)))),\n    };\n  }, [sourceRows]);\n\n  function toggleStatus(s: Status) {\n    setSelectedStatuses((prev) => prev.includes(s) ? prev.filter((x) => x !== s) : [...prev, s]);\n  }\n\n  return (\n    <main className="v112-signals-page">\n      <section className="v112-section">\n        <div className="v112-label">訊號區間</div>\n        <div className="v112-segment">\n          {([\'today\', \'5\', \'10\', \'20\'] as const).map((p) => (\n            <button key={p} type="button" className={period === p ? \'active\' : \'\'} onClick={() => setPeriod(p)} disabled={p !== \'today\'}>\n              {p === \'today\' ? \'今日\' : `${p}日`}\n            </button>\n          ))}\n        </div>\n      </section>\n\n      <section className="v112-section">\n        <h1>今日訊號</h1>\n        <DataQuality data={data} />\n        <div className="v112-focus-grid">\n          <FocusCard title="淨資金流入最多" row={focus.inflow} kind="red" />\n          <FocusCard title="淨資金流出最多" row={focus.outflow} kind="green" />\n          <FocusCard title="最多 ETF 加碼" row={focus.mostAdd} kind="red" />\n          <FocusCard title="最多 ETF 減碼" row={focus.mostReduce} kind="green" />\n        </div>\n      </section>\n\n      <section className="v112-section v112-list-section">\n        <h2>資金交易明細：共 {fmt0(rows.length)} 檔</h2>\n        <div className="v112-status-row">\n          {STATUSES.map((s) => <StatusPill key={s} label={s} count={statusCount[s]} active={selectedStatuses.includes(s)} onClick={() => toggleStatus(s)} />)}\n        </div>\n        <div className="v112-sort-row" aria-label="排序">\n          <SortPill label="淨流入" active={sortKey === \'inflow\'} onClick={() => setSortKey(\'inflow\')} />\n          <SortPill label="淨流出" active={sortKey === \'outflow\'} onClick={() => setSortKey(\'outflow\')} />\n          <SortPill label="絕對金額" active={sortKey === \'abs_amount\'} onClick={() => setSortKey(\'abs_amount\')} />\n          <SortPill label="張數" active={sortKey === \'lots\'} onClick={() => setSortKey(\'lots\')} />\n          <SortPill label="買進ETF" active={sortKey === \'buy\'} onClick={() => setSortKey(\'buy\')} />\n          <SortPill label="賣出ETF" active={sortKey === \'sell\'} onClick={() => setSortKey(\'sell\')} />\n          <SortPill label="股價" active={sortKey === \'price\'} onClick={() => setSortKey(\'price\')} />\n          <SortPill label="漲跌幅" active={sortKey === \'pct\'} onClick={() => setSortKey(\'pct\')} />\n        </div>\n        <div className="v112-table-head"><span>標的</span><span>股價</span><span>淨額 / 張數</span><span>狀態 / 共識</span></div>\n        <div className="v112-rows">\n          {rows.length ? rows.map((row, idx) => <SignalRow row={row} key={`${codeOf(row)}-${idx}`} />) : <div className="v112-no-data">目前沒有符合篩選的今日訊號。</div>}\n        </div>\n      </section>\n    </main>\n  );\n}\n'
home_page = "\nimport SignalsClient from '@/components/SignalsClient';\nimport { getSignalsV112 } from '@/lib/signalsV112';\n\nexport const dynamic = 'force-dynamic';\nexport const revalidate = 0;\n\nexport default async function Page() {\n  const data = await getSignalsV112();\n  return <SignalsClient data={data} />;\n}\n"
css = '\n/* ===== V112 signal logic + mobile UI cleanup ===== */\n.v112-signals-page{width:100%;max-width:920px;margin:0 auto;padding:22px 18px 80px;color:#111827;}\n.v112-section{margin:0 0 28px;}\n.v112-label{font-size:22px;font-weight:900;color:#7b8798;margin:0 0 12px;}\n.v112-segment{display:grid;grid-template-columns:repeat(4,1fr);gap:0;background:#edf3fa;border:1px solid #dbe4ef;border-radius:999px;padding:6px;box-shadow:inset 0 1px 2px rgba(15,23,42,.06);}\n.v112-segment button{border:0;background:transparent;border-radius:999px;font-size:24px;font-weight:900;color:#637083;padding:12px 4px;}\n.v112-segment button.active{background:#fff;color:#2765bd;box-shadow:0 6px 16px rgba(31,95,178,.12);}\n.v112-segment button:disabled{opacity:.78;}\n.v112-section h1{font-size:44px;line-height:1.05;margin:0 0 12px;font-weight:1000;letter-spacing:-.04em;}\n.v112-section h2{font-size:34px;line-height:1.1;margin:0 0 14px;font-weight:1000;letter-spacing:-.04em;}\n.v112-quality{margin:0 0 16px;color:#778397;font-size:17px;font-weight:800;line-height:1.45;}\n.v112-quality-main{font-size:18px;color:#64748b;font-weight:900;margin-bottom:2px;}\n.v112-quality-sub b{color:#111827;}\n.v112-warn{display:block;color:#b7791f;margin-top:3px;}\n.v112-focus-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;}\n.v112-focus-card{display:block;text-decoration:none;border-radius:18px;padding:16px 16px 14px;border:1.5px solid #e5eaf2;min-height:156px;color:#111827;background:#fff;}\n.v112-focus-card.red{background:#fff8f8;border-color:#f7cbd1;}\n.v112-focus-card.green{background:#f2fffa;border-color:#bfeedd;}\n.v112-focus-title{font-size:22px;font-weight:1000;margin-bottom:10px;}\n.v112-focus-card.red .v112-focus-title{color:#df5361;}\n.v112-focus-card.green .v112-focus-title{color:#22a879;}\n.v112-focus-name{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;font-size:26px;font-weight:1000;line-height:1.1;margin-bottom:4px;}\n.v112-focus-name em{font-style:normal;font-size:17px;color:#8995a8;font-weight:900;}\n.v112-focus-price{display:flex;align-items:baseline;gap:8px;margin-bottom:8px;}\n.v112-focus-price span{font-size:36px;font-weight:1000;letter-spacing:-.03em;}\n.v112-focus-price b{font-size:20px;font-weight:1000;}\n.v112-focus-meta{font-size:17px;line-height:1.35;color:#7b8798;font-weight:900;display:grid;gap:1px;}\n.v112-focus-meta b{font-size:18px;}\n.v112-empty{font-size:18px;color:#8390a2;font-weight:900;margin-top:20px;}\n.v112-status-row,.v112-sort-row{display:flex;gap:10px;overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none;padding:0 0 8px;}\n.v112-status-row::-webkit-scrollbar,.v112-sort-row::-webkit-scrollbar{display:none;}\n.v112-status-pill,.v112-sort-pill{border:2px solid #cbd5e1;background:#fff;border-radius:999px;padding:9px 15px;font-size:20px;font-weight:1000;color:#667386;white-space:nowrap;}\n.v112-status-pill.active.s-新增{border-color:#c9ab00;color:#b59b00;background:#fffdf0;}\n.v112-status-pill.active.s-刪除{border-color:#a9b2bf;color:#6b7280;background:#f8fafc;}\n.v112-status-pill.active.s-加碼{border-color:#df5361;color:#df5361;background:#fff8f8;}\n.v112-status-pill.active.s-減碼{border-color:#22a879;color:#22a879;background:#f2fffa;}\n.v112-sort-pill.active{border-color:#bfdbfe;background:#eff6ff;color:#2765bd;}\n.v112-table-head{display:grid;grid-template-columns:1.2fr .75fr 1fr .95fr;gap:8px;background:#f3f6fa;color:#667386;font-size:16px;font-weight:1000;padding:11px 12px;border-radius:14px 14px 0 0;margin-top:4px;}\n.v112-rows{border-top:1px solid #e5eaf2;}\n.v112-row{display:block;text-decoration:none;color:#111827;padding:16px 8px;border-bottom:1px solid #e5eaf2;}\n.v112-r-main{display:grid;grid-template-columns:1.2fr .75fr 1fr .95fr;gap:8px;align-items:center;}\n.v112-r-name{font-size:24px;font-weight:1000;line-height:1.05;min-width:0;}\n.v112-r-name span{display:block;font-size:18px;color:#8995a8;font-weight:900;margin-top:3px;}\n.v112-r-price span{font-size:25px;font-weight:1000;line-height:1.1;}\n.v112-r-price b{display:block;font-size:17px;font-weight:1000;margin-top:2px;}\n.v112-r-amount b{display:block;font-size:22px;font-weight:1000;line-height:1.05;}\n.v112-r-amount span{display:block;font-size:18px;font-weight:1000;margin-top:4px;}\n.v112-r-sub{display:flex;justify-content:flex-end;gap:10px;align-items:center;margin-top:8px;font-size:17px;font-weight:1000;color:#64748b;}\n.v112-status{border-radius:999px;padding:5px 10px;font-size:17px;font-weight:1000;}\n.v112-status.s-新增{background:#fff5c2;color:#b59b00;}\n.v112-status.s-加碼{background:#ffe8ec;color:#df5361;}\n.v112-status.s-減碼,.v112-status.s-刪除{background:#dcfce7;color:#22a879;}\n.v112-limit{border-radius:8px;padding:3px 7px;font-size:15px;}\n.v112-limit.up{background:#df5361;color:#fff;}.v112-limit.down{background:#22a879;color:#fff;}\n.limit-up{display:inline-block;background:#df5361;color:#fff;border-radius:8px;padding:1px 6px;}.limit-down{display:inline-block;background:#22a879;color:#fff;border-radius:8px;padding:1px 6px;}\n.red{color:#df5361!important;}.green{color:#22a879!important;}.muted{color:#8995a8!important;}\n.v112-no-data{padding:24px;text-align:center;color:#8390a2;font-size:18px;font-weight:900;}\n@media (max-width: 520px){\n  .v112-signals-page{padding:18px 17px 70px;}\n  .v112-section h1{font-size:42px;}\n  .v112-section h2{font-size:34px;}\n  .v112-focus-grid{grid-template-columns:1fr 1fr;gap:11px;}\n  .v112-focus-card{padding:14px 13px;min-height:164px;}\n  .v112-focus-title{font-size:21px;}\n  .v112-focus-name{font-size:25px;}\n  .v112-focus-price span{font-size:34px;}\n  .v112-focus-meta{font-size:16px;}\n  .v112-table-head{display:none;}\n  .v112-row{padding:15px 0;}\n  .v112-r-main{grid-template-columns:1.08fr .72fr 1fr;gap:8px;}\n  .v112-r-main .v112-r-amount{grid-column:3;grid-row:1;}\n  .v112-r-name{font-size:24px;}\n  .v112-r-price span{font-size:25px;}\n  .v112-r-sub{justify-content:flex-start;margin-left:0;gap:8px;font-size:17px;}\n}\n@media (min-width: 760px){.v112-signals-page{max-width:760px;}}\n/* ===== end V112 ===== */\n'
readme_content = '\n# V112 今日訊號資料邏輯與手機 UI 修正\n\n這版修正：\n\n1. 今日訊號只統計同一個 target date，不混入前一天資料。\n2. 顯示 `已取得今日資料：X / 27 檔`，若有 ETF 未更新會明確提示。\n3. 今日四張重點卡改成固定資訊層級：股價、漲跌幅、淨額、張數、買賣共識。\n4. 資金交易明細改成手機友善 list，避免卡片過大與欄位擁擠。\n5. 排序名稱改清楚：淨流入、淨流出、絕對金額、張數、買進ETF、賣出ETF、股價、漲跌幅。\n6. 每筆交易明細可點進個股頁 `/stock/{code}`。\n7. 漲停 / 跌停會以股價底色標示。\n\n如果本機 `npm run build` 出現 `supabaseUrl is required`，代表本機沒有 `.env.local`。Vercel 有環境變數的話可以直接 push。\n'

